const upd = $('Telegram Trigger').first().json;
const cb = upd.callback_query;
const msg = cb ? cb.message : upd.message;
const chatId = String(msg.chat.id);
const raw = cb ? String(cb.data || '') : String(msg.text || '').trim();
const low = raw.toLowerCase();
const norm = s => String(s || '').toLowerCase().replace(/ё/g, 'е').replace(/метро/g, '').trim();
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const allUsers = $('Get Users').all().map(i => i.json).filter(u => u.chat_id !== undefined && String(u.chat_id).trim() !== '');
// если в таблице дубли одного chat_id, берём самую нижнюю (последнюю) строку
const users = [...new Map(allUsers.map(u => [String(u.chat_id).trim(), u])).values()];
const places = $input.all().map(i => i.json).filter(p => p.name);
const me = users.find(u => String(u.chat_id).trim() === chatId);
const state = me ? String(me.state || 'done') : '';

const base = () => ({
  chat_id: chatId,
  name: me ? (me.name || '') : '',
  age: me ? (me.age || '') : '',
  metro: me ? (me.metro || '') : '',
  state: me ? (me.state || 'done') : '',
  points: me ? (me.points || 0) : 0,
  hobbies: me ? (me.hobbies || '') : ''
});
const reply = (type, text, saveData) => [{ json: { chat_id: chatId, reply_type: type, reply_text: text, save: !!saveData, saveData: saveData || {} } }];

const Q = {
  ask_name: 'Как тебя зовут?',
  ask_age: 'Сколько тебе лет? Напиши цифрой.',
  ask_metro: 'Какая станция метро рядом с тобой? Я буду предлагать места поблизости.'
};

// ---- Знакомство ----
if (!me) {
  return reply('plain', 'Привет! Я Task Bot 👋\nПомогаю находить бесплатные и недорогие места в Москве.\n\nДавай познакомимся! ' + Q.ask_name, { ...base(), state: 'ask_name' });
}
if (Q[state]) {
  const isText = !cb && raw !== '' && !raw.startsWith('/');
  if (!isText) return reply('plain', Q[state]);
  if (state === 'ask_name') {
    if (raw.length > 40) return reply('plain', 'Имя слишком длинное. Напиши, пожалуйста, короче.');
    return reply('plain', 'Приятно познакомиться, ' + raw + '! ' + Q.ask_age, { ...base(), name: raw, state: 'ask_age' });
  }
  if (state === 'ask_age') {
    const age = parseInt(raw, 10);
    if (!/^\d{1,3}$/.test(raw) || age < 10 || age > 100) return reply('plain', 'Напиши возраст цифрами, например: 21');
    return reply('plain', Q.ask_metro, { ...base(), age: String(age), state: 'ask_metro' });
  }
  if (raw.length > 40) return reply('plain', 'Название слишком длинное. Напиши только станцию метро.');
  return reply('main_menu', 'Готово! Теперь я буду предлагать места рядом со станцией «' + raw + '».\n\nГлавное меню. Выбери, что хочешь сделать:', { ...base(), metro: raw, state: 'done' });
}

// ---- Меню и разделы ----
const greetings = ['hello', 'hi', 'привет', 'здравствуй', 'здравствуйте', 'хай', 'start'];
if (raw === '' || low.startsWith('/start') || low.startsWith('/menu') || raw === 'menu') {
  return reply('main_menu', 'Главное меню. Выбери, что хочешь сделать:');
}
if (greetings.includes(low)) {
  return reply('main_menu', 'Привет! Выбери, что хочешь сделать:');
}
if (raw === 'profile') {
  return reply('profile', '👤 Мой профиль\n\nИмя: ' + (me.name || '—') + '\nВозраст: ' + (me.age || '—') + '\nМетро: ' + (me.metro || '—') + '\nБаллы: ' + (me.points || 0));
}
if (raw === 'edit') {
  return reply('plain', 'Давай обновим анкету. ' + Q.ask_name, { ...base(), state: 'ask_name' });
}
if (raw === 'rating') {
  const top = users.map(u => ({ name: u.name || 'Без имени', points: Number(u.points) || 0 }))
    .filter(u => u.points > 0).sort((a, b) => b.points - a.points).slice(0, 10);
  if (!top.length) return reply('back', '🏆 Рейтинг пока пуст. Скоро здесь появятся лучшие участники!');
  return reply('back', '🏆 Топ участников:\n\n' + top.map((u, i) => (i + 1) + '. ' + u.name + ' — ' + u.points).join('\n'));
}
if (raw === 'walks') {
  return reply('walks', '🚶 Прогулки. Выбери категорию, найди места рядом со своим метро или просто напиши, что ищешь:');
}

// ---- Подборки мест ----
const myMetro = norm(me.metro);
const isNear = p => {
  const m = norm(p.metro);
  return myMetro.length >= 3 && m.length >= 3 && (m === myMetro || m.includes(myMetro) || myMetro.includes(m));
};
const nearFirst = (a, b) => (isNear(a) ? 0 : 1) - (isNear(b) ? 0 : 1);
const noResult = 'Ничего не нашёл 🤔 Попробуй другие слова (например: «парк», «метро Китай-город», «фото») или выбери категорию:';

let found = [];
let header = '';
const q = norm(raw);
const freeRequested = /бесплат/.test(q);
const freeOnly = arr => freeRequested ? arr.filter(p => /бесплат/.test(norm(p.budget))) : arr;
const intentCategory = text => {
  if (/зоопарк|зоосад|животн/.test(text)) return 'зоопарк';
  if (/панорам|смотров|видов/.test(text)) return 'панорама';
  if (/музе|музей|музеи|экспозиц/.test(text)) return 'музей';
  if (/искусств|галере|выставк/.test(text)) return 'искусство';
  if (/парк|парки|сквер|саду|сады/.test(text)) return 'парк';
  if (/прогул|погуля|гулять|маршрут|набереж/.test(text)) return 'прогулка';
  return '';
};
const categoryMatches = (p, cat) => norm(p.category) === cat;
const metroQuery = q.match(/(?:метро|станци[яией]|м\.)\s+([а-яa-zё\- ]{3,50})/i);
const metroTerm = metroQuery ? norm(metroQuery[1]).replace(/[?!.]+$/, '').trim() : '';

if (raw === 'near') {
  found = places.filter(isNear);
  header = '📍 Места рядом с метро «' + (me.metro || '—') + '»:';
  if (!found.length) return reply('walks', 'Рядом с твоим метро пока нет подтверждённых мест. Выбери категорию или попробуй другой запрос:');
} else if (raw === 'random' || low.startsWith('/places')) {
  if (places.length) found = [places[Math.floor(Math.random() * places.length)]];
  header = '🎲 Случайное место для тебя:';
} else if (raw.startsWith('cat:')) {
  const c = intentCategory(norm(raw.slice(4))) || norm(raw.slice(4));
  found = places.filter(p => categoryMatches(p, c)).sort(nearFirst);
  header = 'Категория «' + raw.slice(4) + '»:';
  if (!found.length) return reply('walks', 'В категории «' + raw.slice(4) + '» пока нет подтверждённых мест. Выбери другую категорию:');
} else {
  const cat = intentCategory(q);
  let pool = freeOnly(places);
  if (cat) pool = pool.filter(p => categoryMatches(p, cat));
  if (metroTerm) pool = pool.filter(p => norm(p.metro).includes(metroTerm) || metroTerm.includes(norm(p.metro)) && norm(p.metro).length >= 3);
  if (cat || freeRequested || metroTerm) {
    found = pool.sort(nearFirst);
  } else {
    const stop = new Set(['где','что','как','для','или','есть','мне','хочу','можно','место','места','куда','сходить','недалеко','рядом','покажи','найди','подскажи','посоветуй','какие','есть','москве','москва']);
    const words = q.split(/[^а-яa-z0-9]+/).filter(w => w.length >= 3 && !stop.has(w));
    found = words.length ? pool.map(p => {
      const hay = norm([p.name, p.address, p.metro, p.category, p.best_for, p.description].join(' '));
      const score = words.reduce((sum,w) => sum + Number(hay.includes(w.slice(0, Math.min(5,w.length)))),0);
      return {p,score};
    }).filter(x=>x.score>0).sort((a,b)=>(b.score-a.score)||nearFirst(a.p,b.p)).map(x=>x.p) : [];
  }
  header = 'Вот что нашёл по запросу «' + raw + '»:';
  if (!found.length) {
    const detail = freeRequested ? ' бесплатных' : cat ? ' категории «' + cat + '»' : '';
    return reply('walks', 'По запросу «' + raw + '» нет подтверждённых' + detail + ' мест в каталоге. Попробуй другой запрос или выбери категорию:');
  }
}
if (!found.length) return reply('walks', 'В проверенном каталоге пока нет доступных мест.');

return found.slice(0, 5).map((p, i) => {
  let cap = (i === 0 ? esc(header) + '\n\n' : '') + '<b>' + esc(p.name) + '</b>\n📍 ' + esc(p.address);
  if (p.metro) cap += '\n🚇 ' + esc(p.metro) + (isNear(p) ? ' (рядом с тобой)' : '');
  if (p.inrun_date_line) cap += '\n' + esc(p.inrun_date_line);
  if (p.budget) cap += '\n💰 ' + esc(p.budget);
  if (p.opening_hours) cap += '\n🕒 ' + esc(p.opening_hours);
  if (p.description) cap += '\n\n' + esc(String(p.description).slice(0, 600));
  const photo = String(p.photo_url || '').trim();
  if (photo && p.photo_credit) cap += '\n\n📷 ' + esc(p.photo_credit);
  const map = String(p.map_url || '').trim() || ('https://yandex.ru/maps/?text=' + encodeURIComponent(p.name + ', Москва'));
  return { json: { chat_id: chatId, reply_type: 'cards', save: false, saveData: {}, caption: cap, photo_url: photo, hasPhoto: /^https?:\/\//i.test(photo), map_url: map } };
});

// Prepare Places: данные из листа «Проверенный каталог» -> поля бота
// (даты: логика из n8n_code_event_dates.js команды Inrun)
// ===== НАСТРОЙКИ =====
// Правило команды Inrun: показываем только строки, где inrun_publication разрешает публикацию
// (значение содержит «публик», но не «не публик» / «архив» / «не дублировать»).
// Сейчас в листе нет ни одной такой строки (значения вида «После геокодирования»), поэтому бот будет пустым.
const PUBLISH_VALUES = ['публик'];
const BLOCK_VALUES = ['не публик', 'архив', 'не дублир'];
const ALLOW_ROWS_WITHOUT_STATUS = false;

// ТОЛЬКО ДЛЯ ПРИВАТНОГО ТЕСТА: true показывает строки со статусом verification_status = «Подтверждено»,
// даже если inrun_publication ещё не разрешает публикацию. Перед пилотом вернуть false.
const TEST_MODE = true;

// Колонки листа «Проверенный каталог»: берётся первая непустая из списка
const COLS = {
  name: ['name_verified', 'name'],
  address: ['address_verified', 'address'],
  metro: ['metro_verified', 'metro'],
  budget: ['price_verified', 'budget'],
  type: ['type'],
  description: ['description_verified', 'description'],
  photo_url: ['photo_url'],
  photo_credit: ['photo_credit_license'],
  map_url: ['map_url'],
  hours: ['opening_hours'],
  date: ['date_or_period', 'event_dates', 'dates'],
};


function toCategory(type, name) {
  const t = norm(type);
  const n = norm(name);

  if (t.includes('зоопарк') || n.includes('зоопарк')) {
    return 'зоопарк';
  }

  if (n.includes('панорам') || t.includes('панорам')) {
    return 'панорама';
  }

  if (t.includes('парк') || n.includes('парк')) {
    return 'парк';
  }

  if (
    t.includes('прогул') ||
    t.includes('маршрут') ||
    t.includes('набереж') ||
    t.includes('бульвар')
  ) {
    return 'прогулка';
  }

  if (
    t.includes('музей') ||
    t.includes('экспозиц') ||
    t.includes('усадьб') ||
    t.includes('экскурс') ||
    t.includes('здани')
  ) {
    return 'музей';
  }

  if (t.includes('выставк')) {
    return 'искусство';
  }

  return '';
}


const pick = (row, keys) => { for (const k of keys) { const v = row[k]; if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim(); } return ''; };
const norm = s => String(s || '').toLowerCase().replace(/ё/g, 'е').replace(/\s+/g, ' ').trim();

function isDatePeriod(value) {
  const s = String(value || '').trim();
  return /^(?:постоянно\.?|с\s+\d{1,2}\s+|до\s+\d{1,2}\s+|\d{1,2}(?:\s+и\s+\d{1,2})?\s+[а-яё]+|\d{1,2}[.\/]\d{1,2}[.\/]\d{2,4})/iu.test(s);
}
function splitTitleAndDate(value) {
  const name = String(value || '').trim();
  const match = /\s*\(([^()]*)\)\s*$/u.exec(name);
  if (match && isDatePeriod(match[1])) return { title: name.slice(0, match.index).trim(), period: match[1].trim().replace(/[.\s]+$/u, '') };
  return { title: name, period: '' };
}
function formatDate(value) {
  const period = String(value || '').trim();
  if (!period || /^(?:не\s+подтверждено|неизвестно|нет)$/iu.test(period)) return '';
  if (/^постоянно$/iu.test(period)) return 'Постоянная экспозиция';
  return period.replace(/\s+/gu, ' ').replace(/[.\s]+$/u, '');
}
function isPublishable(row) {
  const s = norm(row.inrun_publication);
  if (BLOCK_VALUES.some(b => s.includes(b))) return false;
  if (PUBLISH_VALUES.some(p => s.includes(p))) return true;
  if (TEST_MODE && norm(row.verification_status) === 'подтверждено') return true;
  if (!Object.prototype.hasOwnProperty.call(row, 'inrun_publication') || !s) return ALLOW_ROWS_WITHOUT_STATUS;
  return false;
}

const out = [];
for (const item of $input.all()) {
  const row = item.json || {};
  if (!isPublishable(row)) continue;
  const parsed = splitTitleAndDate(pick(row, COLS.name));
  if (!parsed.title) continue;
  const date = formatDate(pick(row, COLS.date) || parsed.period);
  const type = pick(row, COLS.type);
  out.push({ json: {
    id: row.id || '',
    name: parsed.title,
    address: pick(row, COLS.address),
    metro: pick(row, COLS.metro),
    budget: pick(row, COLS.budget),
    category: toCategory(type, parsed.title),
    best_for: type,
    description: pick(row, COLS.description),
    photo_url: pick(row, COLS.photo_url),
    photo_credit: pick(row, COLS.photo_credit),
    map_url: pick(row, COLS.map_url),
    opening_hours: pick(row, COLS.hours),
    inrun_date_line: date ? '📅 Даты: ' + date : '',
  } });
}
return out.length ? out : [{ json: {} }];
